\begin{equation*}
T_{m}(\mu ,E)=\sqrt{2E}\,
{\cal T}_{m}\!\Bigl(\mu(2E)^{(m-2)/2}\Bigr),\qquad 
{\cal T}_{m}(0)=2\pi ,
\end{equation*}
for
$H_{m,\mu}=\tfrac12\bigl(p^{2}+q^{2}-\mu q^{m}\bigr)$.
For the pair $n_{1},n_{2}$

\begin{equation*}
\mu_{0}=\frac{2}{n_{1}}\sqrt{\frac{\,n_{2}-n_{1}\,}{n_{1}/2}}
      =\frac{2}{4}\sqrt{\frac{2}{2}}=\frac12 ,
\end{equation*}
and up to an inessential additive constant

\begin{equation*}
H_{1,2}(p,q)=\frac12\Bigl(p^{2}+q^{2}-\mu_{0}q^{2}\Bigr)
          =\frac12p^{2}+\frac{1-\mu_{0}}2q^{2}
          =\frac12p^{2}+\frac14q^{2},
\end{equation*}
i.e. the ordinary harmonic oscillator with
$\omega_{0}^{2}=1-\mu_{0}=1/2$.  For $m=2$

\begin{equation*}
T_{2}(\mu ,E)=\oint\frac{dq}{\sqrt{\,2E-(1-\mu)q^{2}}}
           =\frac{2\pi}{\sqrt{\,1-\mu\,}},
\end{equation*}
so that the hypergeometric factor is $E$ independent.  In the
conventional $ {\cal T}_{m}(0)=2\pi$ normalisation

\begin{equation*}
{\cal T}_{2}(\mu)=\frac{2\pi}{\sqrt{1-\mu}},\qquad 
{\cal T}_{2}(0)=2\pi,
\end{equation*}
and with the normalised ${\cal T}_{m}^{0}={\cal T}_{m}/2\pi$,
${\cal T}_{m}^{0}(0)=1$,

\begin{equation*}
{\cal T}_{2}^{0}(\mu)\equiv1,\qquad0\le\mu<1,
\end{equation*}
the familiar constant $A_{3}\!\!-\!A_{5}$ real period.  In
particular

\begin{equation*}
\alpha_{1}=\frac{n_{1}-1}{\,n_{2}\,}=\frac{4-1}{6}=\frac12,
\qquad {\cal T}_{2}^{0}(\alpha_{1})=1,
\end{equation*}
i.e. in the physical $T(0)=2\pi$ normalisation

\begin{equation*}
T_{2}(E)\equiv\frac{2\pi}{\omega_{0}}
       =\frac{2\pi}{\sqrt{1-\mu_{0}}}=2\pi\sqrt2,\qquad
T_{2}^{h}=\frac{\pi}{\omega_{0}}=\pi\sqrt2,
\end{equation*}
the constant full and half periods of the oscillator
$H_{0}=\tfrac12\bigl(p^{2}+\omega_{0}^{2}q^{2}\bigr)$.  In the
normalised hypergeometric convention ${\cal T}_{m}^{0}(0)=1$ this is the
usual statement ${\cal T}_{2}\equiv1$,
$T_{2}\bigl((n_{1}-1)/n_{2}\bigr)=1$, the $2\pi\sqrt2$ form being the
